class Solution:
    def lengthOfLongestSubstringTwoDistinct(self, s: str) -> int:
        counts = defaultdict(int)
        left = 0
        max_len = 0
        for right, c in enumerate(s):
            counts[c] += 1
            while len(counts) > 2:
                counts[s[left]] -= 1
                if counts[s[left]] == 0:
                    del counts[s[left]]
                left += 1
            max_len = max(max_len, right - left + 1)
        return max_len

