class Solution {
public:
    int lengthOfLongestSubstringTwoDistinct(string s) {
        unordered_map<char, int> counts;
        int left = 0, maxLen = 0;
        for (int right = 0; right < (int)s.size(); ++right) {
            counts[s[right]]++;
            while (counts.size() > 2) {
                if (--counts[s[left]] == 0) counts.erase(s[left]);
                left++;
            }
            maxLen = max(maxLen, right - left + 1);
        }
        return maxLen;
    }
};

